SELECT json_build_object('analise','01_kpis','rows',coalesce(json_agg(row_to_json(q)),'[]'::json)) FROM (WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') SELECT (SELECT count(DISTINCT order_id) FROM p) pedidos,(SELECT count(DISTINCT order_id) FROM p WHERE order_status='delivered') delivered,(SELECT sum(price) FROM i) price,(SELECT sum(freight_value) FROM i) freight_value,(SELECT sum(payment_value) FROM g) payment_value) q;
SELECT json_build_object('analise','02_status','rows',coalesce(json_agg(row_to_json(q)),'[]'::json)) FROM (WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') , dominio AS (SELECT column1 status FROM (VALUES ('approved'),('canceled'),('created'),('delivered'),('invoiced'),('processing'),('shipped'),('unavailable')) s UNION SELECT order_status FROM p), a AS (SELECT order_status,count(DISTINCT order_id) pedidos FROM p GROUP BY order_status) SELECT d.status,coalesce(a.pedidos,0) pedidos,coalesce(a.pedidos,0)*100::numeric/nullif((SELECT count(DISTINCT order_id) FROM p),0) percentual,(SELECT count(DISTINCT order_id) FROM p) denominador FROM dominio d LEFT JOIN a ON a.order_status IS NOT DISTINCT FROM d.status ORDER BY d.status NULLS FIRST) q;
SELECT json_build_object('analise','03_meses','rows',coalesce(json_agg(row_to_json(q)),'[]'::json)) FROM (WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') , a AS (SELECT date_trunc('month',dia)::date mes,count(*) itens,sum(price) price,sum(freight_value) freight_value FROM i GROUP BY 1) SELECT make_date(2017,n,1) mes,coalesce(a.itens,0) itens,a.price,a.freight_value FROM generate_series(1,12) n LEFT JOIN a ON a.mes=make_date(2017,n,1) ORDER BY 1) q;
SELECT json_build_object('analise','04_categorias','rows',coalesce(json_agg(row_to_json(q)),'[]'::json)) FROM (WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') , a AS (SELECT d.membro_tipo,d.product_category_name,count(*) itens,sum(i.price) price,sum(i.freight_value) freight_value FROM i LEFT JOIN gold.dim_produtos d ON d.produto_sk=i.produto_sk GROUP BY 1,2) SELECT rank() OVER(ORDER BY price DESC NULLS LAST) posicao,a.* FROM a ORDER BY price DESC NULLS LAST,product_category_name NULLS FIRST,membro_tipo) q;
SELECT json_build_object('analise','05_vendedores','rows',coalesce(json_agg(row_to_json(q)),'[]'::json)) FROM (WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') , a AS (SELECT i.vendedor_sk,d.seller_id,d.membro_tipo,'Vendedor '||i.vendedor_sk rotulo,count(*) itens,sum(i.price) price,sum(i.freight_value) freight_value FROM i LEFT JOIN gold.dim_vendedores d ON d.vendedor_sk=i.vendedor_sk GROUP BY 1,2,3) SELECT rank() OVER(ORDER BY price DESC NULLS LAST) posicao,a.* FROM a ORDER BY price DESC NULLS LAST,vendedor_sk) q;
SELECT json_build_object('analise','06_metodos','rows',coalesce(json_agg(row_to_json(q)),'[]'::json)) FROM (WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') , a AS (SELECT forma_pagamento_sk,count(*) registros,count(DISTINCT order_id) pedidos,sum(payment_value) payment_value FROM g GROUP BY 1) SELECT d.forma_pagamento_sk,d.payment_type,d.membro_tipo,coalesce(a.registros,0) registros,coalesce(a.pedidos,0) pedidos,a.payment_value FROM gold.dim_forma_pagamento d LEFT JOIN a USING(forma_pagamento_sk) ORDER BY d.forma_pagamento_sk) q;
SELECT json_build_object('analise','07_reconciliacao','rows',coalesce(json_agg(row_to_json(q)),'[]'::json)) FROM (WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') , ia AS (SELECT order_id,count(*) itens,sum(price) price,sum(freight_value) freight_value FROM i GROUP BY 1), ga AS (SELECT order_id,count(*) pagamentos,sum(payment_value) payment_value FROM g GROUP BY 1), r AS (SELECT p.order_id,p.order_status,p.mes,ia.itens,ga.pagamentos,ia.price,ia.freight_value,ga.payment_value,ga.payment_value-ia.price-ia.freight_value diferenca FROM p LEFT JOIN ia USING(order_id) LEFT JOIN ga USING(order_id)) SELECT CASE WHEN grouping(order_status)=0 THEN 'status' WHEN grouping(mes)=0 THEN 'mes' ELSE 'total' END nivel,order_status,mes,count(*) pedidos,count(*) FILTER(WHERE itens IS NULL) sem_itens,count(*) FILTER(WHERE pagamentos IS NULL) sem_pagamentos,count(diferenca) comparaveis,count(*) FILTER(WHERE diferenca<>0) diferencas_nao_zero,count(*) FILTER(WHERE abs(diferenca)>0.01) divergencias,sum(price) price,sum(freight_value) freight_value,sum(payment_value) payment_value,sum(diferenca) diferenca_comparaveis FROM r GROUP BY GROUPING SETS((),(order_status),(mes)) ORDER BY 1,2,3) q;
SELECT json_build_object('analise','08_diferencas_pedido','rows',coalesce(json_agg(row_to_json(q)),'[]'::json)) FROM (WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') , ia AS (SELECT order_id,count(*) itens,sum(price) price,sum(freight_value) freight_value FROM i GROUP BY 1), ga AS (SELECT order_id,count(*) pagamentos,sum(payment_value) payment_value FROM g GROUP BY 1), r AS (SELECT p.order_id,p.order_status,p.mes,ia.itens,ga.pagamentos,ia.price,ia.freight_value,ga.payment_value,ga.payment_value-ia.price-ia.freight_value diferenca FROM p LEFT JOIN ia USING(order_id) LEFT JOIN ga USING(order_id)) SELECT * FROM r WHERE diferenca IS NULL OR diferenca<>0 ORDER BY order_id) q;
SELECT json_build_object('analise','09_fatos','rows',coalesce(json_agg(row_to_json(q)),'[]'::json)) FROM (WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') SELECT 'fato_pedidos' fato,count(*) linhas,count(DISTINCT order_id) pedidos,NULL::numeric price,NULL::numeric freight_value,NULL::numeric payment_value FROM p UNION ALL SELECT 'fato_itens_pedido' fato,count(*) linhas,count(DISTINCT order_id) pedidos,sum(price) price,sum(freight_value) freight_value,NULL::numeric payment_value FROM i UNION ALL SELECT 'fato_pagamentos' fato,count(*) linhas,count(DISTINCT order_id) pedidos,NULL::numeric price,NULL::numeric freight_value,sum(payment_value) payment_value FROM g) q;
